add_action( 'pre_get_posts', 'perfectpixel_exclude_categories_from_feed' );

function perfectpixel_exclude_categories_from_feed( $query ) {
	if ( is_admin() || ! $query->is_main_query() || ! $query->is_feed() || $query->is_comment_feed() || $query->is_category() ) {
		return;
	}
	$ids = array_filter( array_map( 'absint', explode( ',', '{{feed_excluded_categories}}' ) ) );
	if ( $ids ) {
		$query->set( 'category__not_in', array_merge( (array) $query->get( 'category__not_in' ), $ids ) );
	}
}
